CREATE TABLE app_users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE conversations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL REFERENCES conversations(id), role VARCHAR(32) NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE preferences (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_users(id), type VARCHAR(64) NOT NULL, preference_value VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL, confidence DOUBLE PRECISION NOT NULL, source_message_id BIGINT REFERENCES messages(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX messages_recent ON messages(conversation_id,id);
CREATE INDEX preferences_active ON preferences(user_id,status);
CREATE INDEX conversations_user ON conversations(user_id);
